import re

_UNIT_SECONDS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_COMPONENT_RE = re.compile(r"(\d+(?:\.\d+)?)\s*([a-zA-Z]+)")
_ISO_RE = re.compile(
    r"^P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?"
    r"(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?$"
)


def _finish(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # Bare non-negative integer -> seconds
    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601 duration
    if s[0] in "Pp":
        m = _ISO_RE.match(s if s[0] == "P" else "P" + s[1:])
        if m and any(g is not None for g in m.groups()):
            w, d, h, mn, sec = m.groups()
            total = 0.0
            total += float(w or 0) * 604800
            total += float(d or 0) * 86400
            total += float(h or 0) * 3600
            total += float(mn or 0) * 60
            total += float(sec or 0)
            return _finish(total)
        raise ValueError(f"invalid ISO duration: {text!r}")

    # Clock notation hh:mm:ss or mm:ss
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock notation: {text!r}")
        for p in parts:
            if not re.fullmatch(r"\d+(?:\.\d+)?", p):
                raise ValueError(f"invalid clock notation: {text!r}")
        nums = [float(p) for p in parts]
        if len(nums) == 3:
            h, mn, sec = nums
        else:
            h, mn, sec = 0, nums[0], nums[1]
        return _finish(h * 3600 + mn * 60 + sec)

    # number+unit components
    total = 0.0
    pos = 0
    matched = False
    for m in _COMPONENT_RE.finditer(s):
        # ensure only whitespace between components
        if s[pos:m.start()].strip() != "":
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += float(m.group(1)) * _UNIT_SECONDS[unit]
        pos = m.end()
        matched = True

    if not matched or s[pos:].strip() != "":
        raise ValueError(f"invalid duration: {text!r}")

    return _finish(total)

